classdef EegApi < handle
    % EegApi  Connects a MATLAB application to the EEG_API_Unicorn engine over LSL.
    %   Do not edit this file: the settings are in config.json, and your application is the code
    %   that receives the decisions (see example.m).
    %
    %       api = EegApi(EegApi.loadConfig('config.json'));
    %       api.connect();                      % waits until the console connects this application
    %       api.start();                        % sends the settings of config.json, starts the mode
    %       while api.isConnected()
    %           decision = api.nextDecision(0.2);   % a struct, channels by name; [] if none yet
    %           ...                                 % your application
    %       end
    %       api.close();                        % stops the mode it started, closes the streams
    %
    %   The handshake follows docs/control.md: open the engine's reply streams, create the
    %   command stream (its source_id is the name the console lists), wait until the engine reads
    %   it, then send the commands, each with a unique "ref". With the console, someone has to
    %   click "Connect an application", pick this application, then "Connect". With server.py
    %   alone, an application of the same computer is heard at once.
    %
    %   Needs liblsl-Matlab on the path (https://github.com/labstreaminglayer/liblsl-Matlab) and
    %   MATLAB R2016b or later (jsondecode, jsonencode).

    properties (Constant)
        CONTROL_STREAM = 'EEG_API_Unicorn_control';
        REPLIES_STREAM = 'EEG_API_Unicorn_replies';
        DECODED_PREFIX = 'EEG_API_Unicorn_decoded_';
        REPLY_TIMEOUT_S = 5;    % a reply that has not arrived after this long will not arrive
    end

    properties (SetAccess = private)
        Name = ''               % the name the console lists: app_name plus a random part
        Mode = ''
        EngineId = ''           % the engine that answered us first
        StartedHere = false     % true when OUR start_mode started the mode
        Labels = {}             % the channel names of the decoded stream
    end

    properties (Access = private)
        config
        lib
        outlet
        replies = {}            % every reply stream of the network
        replyEngines = {}       % the engine id of each one
        inbox = {}
        disconnection = []      % the engine's "disconnected" message meant for us
        sent = 0
        decoded = []
        log
    end

    methods (Static)
        function config = loadConfig(path)
            % The settings of config.json, completed with the defaults.
            defaults = struct('app_name', 'my-app', 'mode', 'ssvep', 'params', struct(), ...
                              'propose_refresh_hz', 0, 'stop_mode_on_exit', true, ...
                              'search_timeout_s', 30);
            read = jsondecode(fileread(path));
            unknown = setdiff(fieldnames(read), fieldnames(defaults));
            if ~isempty(unknown)
                error('EegApi:config', '%s: unknown setting(s) %s; known: %s', path, ...
                      strjoin(unknown, ', '), strjoin(fieldnames(defaults), ', '));
            end
            config = defaults;
            for f = fieldnames(read)'
                config.(f{1}) = read.(f{1});
            end
        end
    end

    methods
        function self = EegApi(config, log)
            if nargin < 2
                log = @(message) fprintf('%s\n', message);
            end
            self.config = config;
            self.log = log;
            self.lib = lsl_loadlib();
            % A random part makes the name unique: two copies of the application, on one computer
            % or on several, never take each other's replies.
            self.Name = sprintf('%s-%06x', config.app_name, randi([0, 16^6 - 1]));
            self.Mode = config.mode;
            info = lsl_streaminfo(self.lib, EegApi.CONTROL_STREAM, 'Markers', 1, 0, ...
                                  'cf_string', self.Name);
            self.outlet = lsl_outlet(info);
        end

        % --- the handshake ---------------------------------------------------------------------

        function connect(self)
            % Opens the reply streams of the network, then waits (with no time limit) until the
            % engine reads our command stream. Fails when no engine runs.
            started = tic;
            while isempty(self.replies) && toc(started) < self.config.search_timeout_s
                % `minimum` is never reached: the call waits the whole second and returns EVERY
                % reply stream that answered (there may be several engines on the network).
                infos = lsl_resolve_byprop(self.lib, 'name', EegApi.REPLIES_STREAM, 1000, 1.0);
                seen = {};
                for k = 1:numel(infos)
                    info = infos{k};
                    if any(strcmp(seen, info.uid()))
                        continue
                    end
                    seen{end + 1} = info.uid(); %#ok<AGROW>
                    inlet = lsl_inlet(info);
                    try
                        inlet.open_stream(2.0);        % listen BEFORE the first command
                    catch
                        continue                       % an engine that has just quit
                    end
                    self.replies{end + 1} = inlet;
                    self.replyEngines{end + 1} = EegApi.afterAt(info.source_id());
                end
            end
            if isempty(self.replies)
                error('EegApi:noEngine', ...
                      'no engine on the network: is the console (or server.py) running?');
            end
            % A command pushed before the engine reads our stream is lost: wait for it.
            slices = 0;
            while ~self.outlet.wait_for_consumers(1.0)
                if mod(slices, 10) == 0
                    self.log(sprintf(['Waiting to be connected: in the console, click "Connect an ' ...
                                      'application", pick ''%s'', then "Connect".'], self.Name));
                end
                slices = slices + 1;
            end
            self.log(sprintf('Connected as ''%s''', self.Name));
        end

        function yes = isConnected(self)
            % False as soon as the engine has said it stopped reading our command stream (do
            % not rely on have_consumers() alone: it stays true until our next push).
            self.poll();
            yes = isempty(self.disconnection) && self.outlet.have_consumers();
        end

        function why = whyDisconnected(self)
            d = self.disconnection;
            if isempty(d)
                why = 'no engine reads our commands any more';
            elseif isfield(d, 'cause') && strcmp(d.cause, 'console')
                why = 'disconnected in the console';
            elseif isfield(d, 'cause') && strcmp(d.cause, 'engine_stopped')
                why = 'the engine stopped';
            else
                why = sprintf('disconnected: %s', EegApi.textOf(d, 'reason'));
            end
        end

        % --- commands --------------------------------------------------------------------------

        function reply = send(self, cmd, params)
            % Sends one command of docs/control.md for our mode and returns ITS reply (a
            % struct). Sends it again once if the reply is lost (the four commands are safe to
            % repeat).
            for attempt = 1:2
                if ~self.isConnected()
                    error('EegApi:disconnected', '%s', self.whyDisconnected());
                end
                self.sent = self.sent + 1;
                command = struct('cmd', cmd, 'mode', self.Mode, ...
                                 'ref', sprintf('%s-%d', self.Name, self.sent));
                if nargin > 2
                    command.params = params;
                end
                text = jsonencode(command);
                self.log(['-> ' text]);
                self.outlet.push_sample({text});
                started = tic;
                while toc(started) < EegApi.REPLY_TIMEOUT_S
                    self.poll();
                    for k = 1:numel(self.inbox)
                        r = self.inbox{k};
                        if strcmp(EegApi.textOf(r, 'ref'), command.ref) && ~isfield(r, 'event')
                            self.inbox(k) = [];
                            self.log(['<- ' jsonencode(r)]);
                            reply = r;
                            return
                        end
                    end
                    if ~isempty(self.disconnection)
                        error('EegApi:disconnected', '%s', self.whyDisconnected());
                    end
                    pause(0.02);
                end
            end
            error('EegApi:noReply', '%s: no reply', cmd);
        end

        function reply = start(self)
            % Sends the settings of config.json, then starts the mode. For an SSVEP shown on a
            % screen, `propose_refresh_hz` first asks the engine for frequencies that divide that
            % refresh rate. Returns the start_mode reply; fails on a refusal.
            params = self.config.params;
            if isempty(params) || ~isstruct(params)
                params = struct();
            end
            refresh = double(self.config.propose_refresh_hz);
            if refresh > 0
                proposed = self.send('propose_params', struct('refresh_hz', refresh));
                EegApi.mustBeAccepted(proposed, 'propose_params');
                params.refresh_hz = refresh;
                params.(proposed.key) = proposed.value(:)';
            end
            if ~isempty(fieldnames(params))
                EegApi.mustBeAccepted(self.send('set_params', params), 'set_params');
            end
            reply = self.send('start_mode');
            EegApi.mustBeAccepted(reply, 'start_mode');
            % Stop only what WE started: a mode that was already running belongs to someone else.
            self.StartedHere = ~(isfield(reply, 'already_running') && isequal(reply.already_running, true));
            if isfield(reply, 'deferred') && isequal(reply.deferred, true)
                self.log(['This mode needs a model: in the console, choose it, then click ' ...
                          '"Start decoding".']);
            end
        end

        % --- decisions -------------------------------------------------------------------------

        function decision = nextDecision(self, timeout)
            % The next decision of our mode as a struct {channel name: value}, -1 included (-1
            % means "no decision", never target 0); [] when none came within `timeout` seconds
            % (the mode warms up, measures its rest, or waits for a model in the console). Opens
            % the stream again when the engine recreates it.
            decision = [];
            if isempty(self.decoded)
                self.openDecoded();
                if isempty(self.decoded)
                    return
                end
            end
            try
                [sample, ~] = self.decoded.pull_sample(timeout);
            catch
                self.decoded = [];          % the engine recreated the stream: open it again
                return
            end
            if isempty(sample)
                return
            end
            decision = struct();
            for k = 1:min(numel(self.Labels), numel(sample))
                decision.(matlab.lang.makeValidName(self.Labels{k})) = double(sample(k));
            end
        end

        % --- the end ---------------------------------------------------------------------------

        function close(self)
            % Stops the mode we started (if `stop_mode_on_exit`), then closes our streams: with
            % the console, the connection ends with them.
            try
                if self.StartedHere && self.config.stop_mode_on_exit && self.isConnected()
                    self.send('stop_mode');
                end
            catch
            end
            self.StartedHere = false;
            self.decoded = [];
            self.replies = {};
            self.replyEngines = {};
            self.outlet = [];
        end
    end

    methods (Access = private)
        function openDecoded(self)
            % The decoded stream of our mode, on OUR engine (every engine publishes under the
            % same name; the source_id "name@engine id" tells them apart), with its channel names.
            if ~isempty(self.EngineId)
                infos = lsl_resolve_byprop(self.lib, 'source_id', ...
                    [EegApi.DECODED_PREFIX self.Mode '@' self.EngineId], 1, 0.5);
            else        % no reply yet: the first engine that publishes this mode
                infos = lsl_resolve_byprop(self.lib, 'name', [EegApi.DECODED_PREFIX self.Mode], 1, 0.5);
            end
            for k = 1:numel(infos)
                inlet = lsl_inlet(infos{k});
                try
                    inlet.open_stream(1.0);
                    full = inlet.info(2.0);
                catch
                    continue
                end
                labels = {};
                channel = full.desc().child('channels').child('channel');
                while ~channel.empty()
                    labels{end + 1} = channel.child_value('label'); %#ok<AGROW>
                    channel = channel.next_sibling();
                end
                if isempty(labels)
                    labels = arrayfun(@(i) sprintf('ch%d', i - 1), 1:full.channel_count(), ...
                                      'UniformOutput', false);
                end
                self.decoded = inlet;
                self.Labels = labels;
                return
            end
        end

        function poll(self)
            % Reads every waiting reply and keeps those meant for us.
            for k = 1:numel(self.replies)
                engine = self.replyEngines{k};
                while true
                    try
                        [sample, ~] = self.replies{k}.pull_sample(0);
                    catch
                        break
                    end
                    if isempty(sample)
                        break
                    end
                    try
                        r = jsondecode(sample{1});
                    catch
                        continue
                    end
                    if ~isstruct(r) || ~isscalar(r)
                        continue
                    end
                    if strcmp(EegApi.textOf(r, 'event'), 'disconnected')
                        if strcmp(EegApi.textOf(r, 'app'), self.Name) && isempty(self.disconnection) ...
                                && (isempty(self.EngineId) || strcmp(self.EngineId, engine))
                            self.disconnection = r;
                        end
                        continue
                    end
                    if ~startsWith(EegApi.textOf(r, 'ref'), [self.Name '-'])
                        continue                % a reply to another application
                    end
                    if isempty(self.EngineId)
                        self.EngineId = engine;
                    end
                    if strcmp(engine, self.EngineId)
                        self.inbox{end + 1} = r;
                    end
                end
            end
        end
    end

    methods (Static, Access = private)
        function text = textOf(s, field)
            % A text field of a message, '' when it is missing or not a text (a null ref).
            text = '';
            if isfield(s, field) && ischar(s.(field))
                text = s.(field);
            end
        end

        function id = afterAt(sourceId)
            at = strfind(sourceId, '@');
            id = '';
            if ~isempty(at)
                id = sourceId(at(1) + 1:end);
            end
        end

        function mustBeAccepted(reply, step)
            if ~(isfield(reply, 'accepted') && isequal(reply.accepted, true))
                error('EegApi:refused', '%s: %s', step, EegApi.textOf(reply, 'reason'));
            end
        end
    end
end
